import static org.junit.Assert.assertNotNull;

public class FastDateFormat_getDateTimeInstance_TriageGen0Test {

    @Test
    public void testGetDateTimeInstance_Basic() {
        int dateStyle = Calendar.SHORT;
        int timeStyle = Calendar.MEDIUM;
        TimeZone timeZone = TimeZone.getTimeZone("UTC");
        Locale locale = Locale.US;

        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        assertNotNull(format);
        assertEquals(timeZone, format.getTimeZone());
        assertEquals(locale, format.getLocale());

        // Verify formatting works
        long now = System.currentTimeMillis();
        String formatted = format.format(now);
        assertNotNull(formatted);
    }

    @Test
    public void testGetDateTimeInstance_NullTimeZone() {
        int dateStyle = Calendar.LONG;
        int timeStyle = Calendar.LONG;
        TimeZone timeZone = null;
        Locale locale = Locale.FRANCE;

        // This tests the branch: if (timeZone != null)
        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        assertNotNull(format);
        assertEquals(locale, format.getLocale());
    }

    @Test
    public void testGetDateTimeInstance_CachingMechanism() {
        int dateStyle = Calendar.DEFAULT;
        int timeStyle = Calendar.DEFAULT;
        TimeZone timeZone = TimeZone.getDefault();
        Locale locale = Locale.ENGLISH;

        // First call to populate cache
        FastDateFormat format1 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);
        // Second call to retrieve from cache
        FastDateFormat format2 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        assertNotNull(format1);
        assertNotNull(format2);
        // The cache should return the exact same instance
        assertEquals(format1, format2);
    }

    @Test
    public void testGetDateTimeInstance_DifferentLocales() {
        int dateStyle = Calendar.MEDIUM;
        int timeStyle = Calendar.MEDIUM;
        TimeZone timeZone = TimeZone.getTimeZone("GMT");

        FastDateFormat formatUS = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, Locale.US);
        FastDateFormat formatUK = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, Locale.UK);

        assertNotNull(formatUS);
        assertNotNull(formatUK);
        // Different locales should result in different cache keys and potentially different patterns
        // But we check they are not the same object if patterns differ
        if (!formatUS.getPattern().equals(formatUK.getPattern())) {
            assertNotNull(formatUS.getPattern());
        }
    }

    @Test
    public void testGetDateTimeInstance_DifferentStyles() {
        TimeZone tz = TimeZone.getDefault();
        Locale loc = Locale.US;

        FastDateFormat style1 = FastDateFormat.getDateTimeInstance(Calendar.SHORT, Calendar.SHORT, tz, loc);
        FastDateFormat style2 = FastDateFormat.getDateTimeInstance(Calendar.LONG, Calendar.LONG, tz, loc);

        assertNotNull(style1);
        assertNotNull(style2);
    }

    @Test
    public void testGetDateTimeInstance_Validation() {
        // Testing with invalid styles to trigger potential exceptions from DateFormat.getDateTimeInstance
        // Note: Depending on the JDK version, passing invalid constants might throw IllegalArgumentException
        try {
            FastDateFormat.getDateTimeInstance(-1, -1, TimeZone.getDefault(), Locale.US);
        } catch (Exception e) {
            // Expected behavior for invalid inputs
        }
    }
}
